  await page.route('**/__editor-local/media/',route=>route.fulfill({json:{schemaVersion:1,revision:0,categories:[],assets:[]}}));
  // Mai chiamate AI a pagamento nella suite automatica browser.
  await page.route('**/__editor-local/admin/', route => route.fulfill({json:{schemaVersion:1,revision:0,settings:{editorName:'TEST',gridMm:1,gridVisible:false,snapEnabled:false},fonts:TEST_FONT_ASSETS.map(({dataBase64,...font})=>({...font,id:font.id.slice(5),actualFamily:font.family,actualWeight:font.weight,actualItalic:font.italic,archived:false})),records:[]}}));
