  const copied = (await state()).objects.at(-1);
  expect(copied).toEqual({ ...editedSource, id: copied.id, text: 'Città' }); expect(copied.id).not.toBe(added.id);
  await page.getByText('Strumenti sviluppatore').click();
  await page.getByLabel('Comando AI simulato').fill(JSON.stringify({ schemaVersion: 1, tool: 'setText', expectedRevision: 3, objectId: copied.id, arguments: { text: 'AI TEST' } }));
  await page.getByRole('button', { name: 'Esegui comando', exact: true }).click();
