  await clickEditorButton(page, { name: 'Elimina selezionato' });
  expect((await state()).objects.some((o: { id: string }) => o.id === copied.id)).toBe(false);
  await expect(page.getByRole('button', { includeHidden: true, name: 'Duplica selezionato' })).toBeDisabled();
  await page.getByRole('button', { name: 'Annulla', exact: true }).click();
