test('maniglie reali: dilatazione del testo senza cambio corpo e rotazione canonica', async ({ page }) => {
  const errors: string[] = []; page.on('pageerror', error => errors.push(error.message));
  await openProductCanvas(page); await writeOnCanvas(page, 'TEST');
  await expect(page.getByLabel('Larghezza automatica', { exact: true })).toBeChecked();
  await page.getByText('Stato e storico del documento').click();
  const state = async () => JSON.parse(await page.getByTestId('graphic-state').innerText());
  const measure = async () => page.evaluate(async object => {
    const path = '/src/editor/fabric-adapter.ts'; const { measureFabric } = await import(path); return measureFabric(object);
  }, (await state()).objects.find((o: { id: string }) => o.id === 'text-1'));
  const canvas = page.locator('.upper-canvas'); await canvas.scrollIntoViewIfNeeded();
  const box = (await canvas.boundingBox())!, before = (await state()).objects[1], size = await measure();
  const corner = { x: box.x + (before.xMm + size.widthMm) * 8, y: box.y + (before.yMm + size.heightMm) * 8 };
  await page.keyboard.down('Alt'); await page.mouse.move(corner.x, corner.y); await page.mouse.down();
  await page.mouse.move(corner.x + 20, corner.y + 10, { steps: 8 }); await page.mouse.up(); await page.keyboard.up('Alt');
  await expect(page.getByTestId('revision')).toContainText('Revisione grafica: 2 ·');
  const scaled = (await state()).objects[1]; expect(scaled.fontSizePt).toBeGreaterThan(9); expect(scaled.textScaleX).toBeGreaterThan(0); expect(scaled.textBox.autoWidth).toBe(true); expect(scaled.text).toBe('TEST'); expect(scaled).not.toHaveProperty('scaleX');
  const nextSize = await measure(); await canvas.scrollIntoViewIfNeeded(); const nextBox = (await canvas.boundingBox())!;
  const centerX = nextBox.x + (scaled.xMm + nextSize.widthMm / 2) * 8, centerY = nextBox.y + (scaled.yMm + nextSize.heightMm / 2) * 8;
  await page.mouse.move(centerX, nextBox.y + scaled.yMm * 8 - 40); await page.mouse.down();
  await page.mouse.move(centerX + 45, centerY - 45, { steps: 8 }); await page.mouse.up();
  await expect(page.getByTestId('revision')).toContainText('Revisione grafica: 3 ·');
  const rotated = (await state()).objects[1]; expect(rotated.rotationDeg).toBeGreaterThan(20); expect(rotated.rotationDeg).toBeLessThan(80);
  expect(rotated.fontSizePt).toBeCloseTo(scaled.fontSizePt); expect(errors).toEqual([]);
});

