test('vertici e ingombri ruotati del modello corrispondono alle coordinate reali Fabric', async ({ page }) => {
  await page.goto('/');
  const results = await page.evaluate(async () => {
    const modelPath = '/tests/helpers/editor-model.browser.ts', adapterPath = '/src/editor/fabric-adapter.ts';
    const { createDocument, objectGeometry } = await import(modelPath);
    const { FabricAdapter, measureFabric } = await import(adapterPath);
    const canvas = document.createElement('canvas'); document.body.append(canvas);
    const adapter = new FabricAdapter(canvas, () => 0, () => {});
    const results = [];
    for (const angle of [-180, -90, -45, 0, 30, 90, 180]) {
      const doc = createDocument(); doc.objects = [
        { ...doc.objects[0], id: 'r', xMm: 20, yMm: 5, widthMm: 10, heightMm: 4, rotationDeg: angle },
        { ...doc.objects[1], id: 't', xMm: 4, yMm: 5, text: 'TEST', rotationDeg: angle },
        { id: 'e', type: 'ellipse', xMm: 20, yMm: 5, rxMm: 6, ryMm: 2, rotationDeg: angle, strokeMm: 0.25, stroke: '#000000' },
        { id: 'p', type: 'path', xMm: 20, yMm: 5, widthMm: 10, heightMm: 4, points: [{ x: 0, y: 1 }, { x: 0.5, y: 0 }, { x: 1, y: 1 }], closed: false, rotationDeg: angle, strokeMm: 0.25, stroke: '#000000' },
      ];
      adapter.render(doc);
      results.push(...doc.objects.map((object: import('../../src/editor/model').SceneObject, index: number) => {
        const geometry = objectGeometry(object, measureFabric), rendered = adapter.canvas.getObjects()[index];
        const bounds = rendered.getBoundingRect(); const coords = rendered.getCoords();
        return { angle, type: object.type, error: Math.max(Math.abs(bounds.left / 8 - object.xMm), Math.abs(bounds.top / 8 - object.yMm), Math.abs(bounds.width / 8 - geometry.widthMm), Math.abs(bounds.height / 8 - geometry.heightMm), ...coords.flatMap((p: { x: number; y: number }, i: number) => [Math.abs(p.x / 8 - geometry.corners[i].x), Math.abs(p.y / 8 - geometry.corners[i].y)])) };
      }));
    }
    adapter.dispose(); return results;
  });
  for (const result of results) expect(result.error, `${result.type} ${result.angle}°`).toBeLessThan(1e-7);
});

