test('cursori angoli del box orientati correttamente anche dopo rotazione', async ({ page }) => {
  await page.goto('/editor');
  const cursors = await page.evaluate(async () => {
    const path = '/src/editor/fabric-adapter.ts', model = '/tests/helpers/editor-model.browser.ts';
    const { FabricAdapter } = await import(path), { createDocument } = await import(model);
    const element = document.createElement('canvas'); document.body.append(element); const adapter = new FabricAdapter(element, () => 0, () => {});
    const doc = createDocument(); doc.objects = [{ id: 'box', type: 'text', xMm: 10, yMm: 5, text: 'TEST', fontSizePt: 9, fontFamily: 'font-aaaaaaaa-0000-4000-8000-000000000001', fill: '#000000', textBox: { widthMm: 30, heightMm: 5, autoWidth: false, autoHeight: true } }];
    const result: Record<string, string> = {};
    for (const angle of [0, 90]) {
      doc.objects[0].rotationDeg = angle; adapter.render(doc, 'box'); const box = adapter.canvas.getActiveObject();
      for (const corner of ['tl', 'tr', 'bl', 'br']) result[`${angle}-${corner}`] = box.controls[corner].cursorStyleHandler({ shiftKey: false }, box.controls[corner], box, box.oCoords[corner]);
    }
    adapter.dispose(); element.remove(); return result;
  });
  expect(cursors).toMatchObject({ '0-tl': 'nw-resize', '0-tr': 'ne-resize', '0-bl': 'sw-resize', '0-br': 'se-resize', '90-tr': 'se-resize', '90-bl': 'nw-resize' });
});

