for (const grouped of [false, true]) test(`maniglie ${grouped ? 'gruppo' : 'selezione'}: preview e documento coincidono con scala, rotazione ed Esc`, async ({ page }) => {
  await page.goto('/editor');
  await page.evaluate(async ({ objects, grouped }) => {
    const modelPath = '/tests/helpers/editor-model.browser.ts', adapterPath = '/src/editor/fabric-adapter.ts';
    const { DocumentStore, createDocument } = await import(modelPath), { FabricAdapter, measureFabric } = await import(adapterPath);
    const host = document.createElement('div'); host.id = 'transform-harness'; host.style.cssText = 'position:fixed;left:80px;top:100px;z-index:10000;background:white'; document.body.append(host);
    const element = document.createElement('canvas'); host.append(element);
    const doc = createDocument(); doc.objects = objects; if (grouped) doc.groups = [{ id: 'g', objectIds: objects.map(o => o.id) }];
    const store = new DocumentStore(doc, measureFabric);
    const view = new FabricAdapter(element, () => store.document.revision, () => {}, ...Array(10).fill(undefined), (objectIds: string[], args: unknown, expectedRevision: number) => {
      store.dispatch({ schemaVersion: 1, tool: 'transformObjects', objectId: objectIds[0], expectedRevision, arguments: { ...(args as object), objectIds } }, 'manual'); view.render(store.document, objectIds);
    });
    view.render(store.document, objects.map(o => o.id));
    const inspect = () => {
      const active = view.canvas.getActiveObject(); active.setCoords();
      const leaves = (object: any): any[] => typeof object.getObjects === 'function' ? object.getObjects().flatMap(leaves) : [object];
      return { revision: store.document.revision, doc: structuredClone(store.document), scaleX: active.scaleX, scaleY: active.scaleY, angle: active.angle, center: active.getCenterPoint(), br: active.oCoords.br, mtr: active.oCoords.mtr,
        leaves: leaves(active).map((object: any) => {
          object.setCoords();
          if (typeof object.radius === 'number') {
            const center = object.getCenterPoint(), diameter = (object.radius * 2 + object.strokeWidth) * object.getObjectScaling().x;
            return { left: center.x - diameter / 2, top: center.y - diameter / 2, width: diameter, height: diameter };
          }
          return object.getBoundingRect();
        }) };
    };
    (window as any).__transformHarness = { inspect };
  }, { objects: selectionTransformObjects(), grouped });
  const inspect = () => page.evaluate(() => (window as any).__transformHarness.inspect());
  const before = await inspect(), canvas = page.locator('#transform-harness .upper-canvas'), rect = (await canvas.boundingBox())!;
  await page.keyboard.down('Shift'); await page.mouse.move(rect.x + before.br.x, rect.y + before.br.y); await page.mouse.down(); await page.mouse.move(rect.x + before.br.x + 12, rect.y + before.br.y + 10, { steps: 8 }); await page.keyboard.up('Shift');
  const preview = await inspect(); expect(preview.scaleX).toBeGreaterThan(1); expect(preview.scaleX).toBeCloseTo(preview.scaleY, 8); expect(preview.revision).toBe(0);
  await page.mouse.up(); await expect.poll(async () => (await inspect()).revision).toBe(1); const scaled = await inspect();
  for (let i = 0; i < preview.leaves.length; i++) for (const key of ['left', 'top', 'width', 'height']) expect(scaled.leaves[i][key]).toBeCloseTo(preview.leaves[i][key], 4);
  const factor = scaled.doc.objects[1].fontSizePt / 9; expect(scaled.doc.objects[2].radiusMm).toBeCloseTo(2.2 * factor, 7); expect(scaled.doc.objects[0].strokeMm).toBeCloseTo(0.25 * factor, 7);
  const radius = Math.hypot(scaled.mtr.x - scaled.center.x, scaled.mtr.y - scaled.center.y), angle = Math.PI / 6;
  await page.mouse.move(rect.x + scaled.mtr.x, rect.y + scaled.mtr.y); await page.mouse.down(); await page.mouse.move(rect.x + scaled.center.x + Math.sin(angle) * radius, rect.y + scaled.center.y - Math.cos(angle) * radius, { steps: 8 });
  const rotatedPreview = await inspect(); await page.mouse.up(); await expect.poll(async () => (await inspect()).revision).toBe(2); const rotated = await inspect();
  for (let i = 0; i < rotated.leaves.length; i++) for (const key of ['left', 'top', 'width', 'height']) expect(rotated.leaves[i][key]).toBeCloseTo(rotatedPreview.leaves[i][key], 4);
  expect(rotated.doc.objects[1].rotationDeg).toBeCloseTo(rotatedPreview.angle, 8);
  expect(rotated.doc.objects[1].rotationDeg).toBeGreaterThan(29); expect(rotated.doc.objects[1].rotationDeg).toBeLessThan(31);
  await page.mouse.move(rect.x + rotated.br.x, rect.y + rotated.br.y); await page.mouse.down(); await page.mouse.move(rect.x + rotated.br.x + 8, rect.y + rotated.br.y + 8, { steps: 8 }); await page.keyboard.press('Escape'); await page.mouse.up();
  const cancelled = await inspect(); expect(cancelled.revision).toBe(2); expect(cancelled.doc).toEqual(rotated.doc);
});

