for (const zoom of [1, 4]) test(`agganci a zoom ${zoom * 100}%: tolleranza costante sullo schermo`, async ({ page }) => {
  await page.goto('/editor');
  await page.evaluate(async zoom => {
    const model = '/tests/helpers/editor-model.browser.ts', adapter = '/src/editor/fabric-adapter.ts';
    const { createDocument, DocumentStore } = await import(model), { FabricAdapter, measureFabric } = await import(adapter);
    const host = document.createElement('div'); host.id = 'snap-zoom'; host.style.cssText = 'position:fixed;left:80px;top:100px;z-index:10000'; document.body.append(host);
    const element = document.createElement('canvas'); host.append(element); const doc = createDocument();
    doc.objects = [{ id: 'a', type: 'rect', xMm: 10, yMm: 3, widthMm: 6, heightMm: 2, strokeMm: 0.25, stroke: '#000000', fill: '#000000' }];
    const store = new DocumentStore(doc, measureFabric), view = new FabricAdapter(element, () => store.document.revision, (objectId: string, xMm: number, yMm: number, expectedRevision: number) => {
      store.dispatch({ schemaVersion: 1, tool: 'moveObject', objectId, expectedRevision, arguments: { xMm, yMm } }, 'manual'); view.render(store.document, objectId);
    });
    view.render(store.document, 'a'); view.setGuides({ gridVisible: true, snapEnabled: true, gridMm: 1 }); view.setZoom(zoom, store.document);
    (window as any).__snapZoom = () => structuredClone(store.document);
  }, zoom);
  const canvas = page.locator('#snap-zoom .upper-canvas'), bounds = (await canvas.boundingBox())!;
  await page.mouse.move(bounds.x + 13.125 * 8 * zoom, bounds.y + 4.125 * 8 * zoom); await page.mouse.down(); await page.mouse.move(bounds.x + 13.125 * 8 * zoom + 5 * zoom, bounds.y + 4.125 * 8 * zoom + 5 * zoom, { steps: 8 }); await page.mouse.up();
  await expect.poll(() => page.evaluate(() => (window as any).__snapZoom().revision)).toBe(1);
  const result = await page.evaluate(() => (window as any).__snapZoom()); expect(result.objects[0].xMm).toBeCloseTo(zoom === 1 ? 10.875 : 10.625, 7);
});

