for (const kind of ['rect', 'square', 'circle', 'ellipse', 'ellipseCircle'] as const) test(`disegno diretto ${kind}: coordinate del gesto, selezione e undo`, async ({ page }) => {
  await page.goto('/editor'); await page.getByText('Stato e storico del documento').click();
  const state = async () => JSON.parse(await page.getByTestId('graphic-state').innerText()), before = await state();
  const label = kind === 'circle' ? 'Disegna cerchio nel canvas' : kind.startsWith('ellipse') ? 'Disegna ellisse nel canvas' : 'Disegna rettangolo nel canvas';
  await page.getByRole('button', { name: label, exact: true }).click();
  const canvas = page.locator('.upper-canvas'); await expect(canvas).toHaveCSS('cursor', 'crosshair'); await canvas.scrollIntoViewIfNeeded();
  await canvas.evaluate(element => element.addEventListener('mousedown', event => {
    if (!(event instanceof MouseEvent)) return;
    const bounds = element.getBoundingClientRect(); (window as any).__drawingStart = { x: (event.clientX - bounds.x) / 8, y: (event.clientY - bounds.y) / 8 };
  }, { once: true }));
  const bounds = (await canvas.boundingBox())!, start = { x: 25, y: 10 }, end = { x: 20, y: 13 };
  if (kind === 'square' || kind === 'ellipseCircle') await page.keyboard.down('Shift');
  await page.mouse.move(bounds.x + start.x * 8, bounds.y + start.y * 8); await page.mouse.down(); await page.mouse.move(bounds.x + end.x * 8, bounds.y + end.y * 8, { steps: 8 });
  expect(await state()).toEqual(before); await page.mouse.up(); if (kind === 'square' || kind === 'ellipseCircle') await page.keyboard.up('Shift');
  await expect(page.getByTestId('revision')).toContainText('Revisione grafica: 1 ·'); const shape = (await state()).objects.at(-1), actualStart = await page.evaluate(() => (window as any).__drawingStart);
  if (kind === 'circle') {
    expect(shape.type).toBe('circle'); expect(shape.radiusMm).toBeCloseTo(Math.hypot(5, 3), 7); expect(shape.xMm + shape.radiusMm + 0.125).toBeCloseTo(actualStart.x, 7); expect(shape.yMm + shape.radiusMm + 0.125).toBeCloseTo(actualStart.y, 7);
  } else if (kind.startsWith('ellipse')) {
    expect(shape).toMatchObject({ type: 'ellipse', rxMm: 2.5, ryMm: kind === 'ellipseCircle' ? 2.5 : 1.5 });
    expect(shape.xMm).toBeCloseTo(actualStart.x - 5 - 0.125, 7); expect(shape.yMm).toBeCloseTo(actualStart.y - 0.125, 7);
  } else {
    expect(shape).toMatchObject({ type: 'rect', widthMm: 5, heightMm: kind === 'square' ? 5 : 3 });
    expect(shape.xMm).toBeCloseTo(actualStart.x - 5 - 0.125, 7); expect(shape.yMm).toBeCloseTo(actualStart.y - 0.125, 7);
  }
  await expect(page.getByRole('button', { name: label, exact: true })).toHaveAttribute('aria-pressed', 'false');
  await expect(page.getByLabel(kind === 'circle' ? 'Diametro (mm)' : 'Larghezza (mm)', { exact: true })).toBeVisible();
  await page.getByRole('button', { name: 'Annulla', exact: true }).click(); expect((await state()).objects).toEqual(before.objects);
});

