    const bounds = view.canvas.upperCanvasEl.getBoundingClientRect(), click = (x: number, y: number) => view.canvas.fire('mouse:down', { e: new MouseEvent('mousedown', { clientX: bounds.x + x * 8, clientY: bounds.y + y * 8, button: 0 }) });
