// Decode the SVG's visible image viewport, including its native crop clip.
async function visibleRasterPixels(page: Page, svg: string) {
 return page.evaluate(async svg => {
  const xml=new DOMParser().parseFromString(svg,'image/svg+xml'),node=xml.querySelector('image')!;
  const source=node.getAttribute('href')??node.getAttribute('xlink:href')!,image=new Image();image.src=source;await image.decode();
  const clipId=node.getAttribute('clip-path')?.match(/#([^)]*)/)?.[1],rect=clipId?xml.getElementById(clipId)?.querySelector('rect'):null;
  const left=rect?Number(rect.getAttribute('x'))-Number(node.getAttribute('x')):0,top=rect?Number(rect.getAttribute('y'))-Number(node.getAttribute('y')):0;
  const width=rect?Number(rect.getAttribute('width')):image.naturalWidth,height=rect?Number(rect.getAttribute('height')):image.naturalHeight;
  const canvas=document.createElement('canvas');canvas.width=Math.ceil(width);canvas.height=Math.ceil(height);const ctx=canvas.getContext('2d')!;
  ctx.drawImage(image,left,top,width,height,0,0,canvas.width,canvas.height);
  return{width:canvas.width,height:canvas.height,pixels:[...ctx.getImageData(0,0,canvas.width,canvas.height).data]};
 },svg);
}
async function exportedRasterPixels(page: Page) {
 const pending=page.waitForEvent('download');await page.getByRole('button',{name:'Esporta SVG',exact:true}).click();
 const bitmap=await visibleRasterPixels(page,await readFile(await(await pending).path(),'utf8'));
 return{width:bitmap.width,height:bitmap.height,data:bitmap.pixels};
}
