async function pngDownload(page: Page) {
  const pending = page.waitForEvent('download'); await page.getByRole('button', { name: 'Esporta PNG', exact: true }).click(); const download = await pending; return { bytes: await readFile(await download.path()), filename: download.suggestedFilename() };
}
async function pngSamples(page: Page, bytes: Buffer, points: { x: number; y: number }[]) {
  return page.evaluate(async ({ data, points }) => { const image = new Image(); image.src = data; await image.decode(); const canvas = document.createElement('canvas'); canvas.width = image.naturalWidth; canvas.height = image.naturalHeight; const ctx = canvas.getContext('2d')!; ctx.drawImage(image, 0, 0); return { width: canvas.width, height: canvas.height, samples: points.map(point => [...ctx.getImageData(Math.round(point.x * canvas.width), Math.round(point.y * canvas.height), 1, 1).data]) }; }, { data: 'data:image/png;base64,' + bytes.toString('base64'), points });
}
function pngPhysical(bytes: Buffer) {
  for (let offset = 8; offset < bytes.length;) { const length = bytes.readUInt32BE(offset), kind = bytes.toString('ascii', offset + 4, offset + 8); if (kind === 'pHYs') return { x: bytes.readUInt32BE(offset + 8), y: bytes.readUInt32BE(offset + 12), unit: bytes[offset + 16] }; offset += length + 12; } return null;
}
