async function bezierWorldState(page: Page) {
  const object = JSON.parse((await page.getByTestId('graphic-state').textContent())!).objects.at(-1);
  return page.evaluate(async object => { const modelPath = '/tests/helpers/editor-model.browser.ts', nodesPath = '/src/editor/bezier-nodes.ts', adapterPath = '/src/editor/fabric-adapter.ts'; const model = await import(modelPath), nodes = await import(nodesPath), adapter = await import(adapterPath); return { object, center: model.objectCenter(object, adapter.measureFabric), nodes: nodes.bezierWorldNodes(object, adapter.measureFabric), measured: adapter.measureFabric(object) }; }, object);
}
