test('penna Bézier: massimo 64 nodi e revisione iniziale conservata', async ({ page }) => {
  await page.goto('/editor'); const result = await page.evaluate(async () => {
    const adapterPath = '/src/editor/fabric-adapter.ts', modelPath = '/tests/helpers/editor-model.browser.ts'; const { FabricAdapter } = await import(adapterPath), { createDocument } = await import(modelPath);
    const host = document.createElement('div'); host.style.cssText = 'position:fixed;left:80px;top:100px'; document.body.append(host); const element = document.createElement('canvas'); host.append(element); const view = new FabricAdapter(element, () => 7, () => {}), doc = createDocument(); doc.revision = 7; view.render(doc);
    let count = 0, calls = 0; const result = { length: 0, closed: true, revision: -1, count: 0, calls: 0 };
    view.setDrawingTool('bezier', { onPrimitive: () => {}, onStroke: () => {}, onActive: () => {}, onExit: () => {}, onCount: (value: number) => { count = value; }, onCurve: (nodes: unknown[], closed: boolean, revision: number) => { calls++; result.length = nodes.length; result.closed = closed; result.revision = revision; } });
    const bounds = view.canvas.upperCanvasEl.getBoundingClientRect(), click = (x: number, y: number) => { view.canvas.fire('mouse:down', { e: new MouseEvent('mousedown', { clientX: bounds.x + x * 8, clientY: bounds.y + y * 8, button: 0 }) }); view.canvas.fire('mouse:up', { e: new MouseEvent('mouseup') }); };
    click(5, 5); for (let i = 1; i <= 70; i++) click(10 + i * 0.5, 5 + i % 2 * 5); result.count = count; view.finishBezier(false); await Promise.resolve(); result.calls = calls; view.dispose(); host.remove(); return result;
  }); expect(result).toEqual({ length: 64, closed: false, revision: 7, count: 64, calls: 1 });
});
