async function kerningMetrics(page: Page, doc: any) {
  return page.evaluate(async doc => { const path = '/src/editor/fabric-adapter.ts'; const { FabricAdapter } = await import(path), element = document.createElement('canvas'), view = new FabricAdapter(element, () => doc.revision, () => {}); view.render(doc); const object = view.canvas.getObjects()[0]; const result = { width: object.width, lines: object.textLines, bounds: structuredClone(object.__charBounds), widths: object.textLines.map((_: unknown, index: number) => object.getLineWidth(index)), end: object.__getCursorBoundariesOffsets(Array.from(object.text).length), svg: view.exportSvg(doc) }; view.dispose(); return result; }, doc);
}
