    const doc = createDocument(), rect = { id: 'shape', type: 'rect', xMm: 18, yMm: 7, widthMm: 8, heightMm: 4, rotationDeg: angle, strokeMm: .25, stroke: '#000000' }, text = { id: 'shape', type: 'text', xMm: 18, yMm: 4, text: 'TEST TEST TEST', textAlign: 'left', fontFamily: 'font-aaaaaaaa-0000-4000-8000-000000000001', fontSizePt: 9, letterSpacingPt: .2, textScaleX: 1.2, textScaleY: kind === 'text-auto' ? 1 : .8, fill: '#000000', rotationDeg: angle, textBox: { widthMm: 20, heightMm: 4, autoWidth: kind === 'text-auto', autoHeight: true } };
