  await page.getByRole('button', { name: 'Allinea maniglie del nodo', exact: true }).click(); await expect(page.getByTestId('revision')).toContainText('Revisione grafica: 2 ·'); const aligned = await refinementState(page), nodes = await world(); for (const i of [0, 1, 2]) { expect(nodes[i].x).toBeCloseTo(original[i].x, 6); expect(nodes[i].y).toBeCloseTo(original[i].y, 6); } for (const side of ['in', 'out']) expect(length(nodes[1], side)).toBeCloseTo(length(original[1], side), 6);
  await page.getByRole('button', { name: 'Rendi simmetriche le maniglie del nodo', exact: true }).click(); await expect(page.getByTestId('revision')).toContainText('Revisione grafica: 3 ·'); const symmetric = await world(); expect(length(symmetric[1], 'in')).toBeCloseTo(length(original[1], guide), 6); expect(length(symmetric[1], 'out')).toBeCloseTo(length(original[1], guide), 6);
  await page.getByRole('button', { name: 'Annulla', exact: true }).click(); expect((await refinementState(page)).objects).toEqual(aligned.objects); await page.getByRole('button', { name: 'Ripristina', exact: true }).click(); await page.getByRole('button', { name: 'Rimuovi maniglie del nodo', exact: true }).click(); await expect(page.getByTestId('revision')).toContainText('Revisione grafica: 6 ·'); const removed = await refinementState(page); expect(removed.objects[0].nodes[1]).not.toHaveProperty('in'); expect(removed.objects[0].nodes[1]).not.toHaveProperty('out'); await expect(page.getByRole('button', { name: 'Rimuovi maniglie del nodo', exact: true })).toBeDisabled();
  const svgPending = page.waitForEvent('download'); await page.getByRole('button', { name: 'Esporta SVG', exact: true }).click(); const svg = await readFile(await (await svgPending).path(), 'utf8'); const curvePath = [...svg.matchAll(/<path[^>]*d="([^"]*)"/g)].at(-1)![1]!; expect((curvePath.match(/C /g) ?? []).length).toBe(2); expect(svg).not.toMatch(/NaN|Infinity|#0088cc/); const pending = page.waitForEvent('download'); await page.getByRole('button', { name: 'Esporta JSON', exact: true }).click(); await page.getByLabel('Riapri progetto JSON').setInputFiles(await (await pending).path()); expect((await refinementState(page)).objects).toEqual(removed.objects);
