async function templateArchive(page:Page,wide=false,blue=false){
 const {mkdtemp,rm}=await import('node:fs/promises'),{join}=await import('node:path'),{tmpdir}=await import('node:os'),{EditorAdminStore,adminSnapshot}=await import('../../scripts/editor-admin-store'),{fixtureCatalog}=await import('../../src/catalog/adapter'),{profileKey}=await import('../../src/catalog/schema');
 const directory=await mkdtemp(join(tmpdir(),'template-flow-')),store=new EditorAdminStore(directory),products=fixtureCatalog.list(),large=products.find(p=>p.handle==='trodat-4915')!,doc=createTestDocument(large,fixtureCatalog.version);
 doc.objects=wide?[{id:'frame',type:'rect',xMm:5,yMm:3,widthMm:56,heightMm:18,strokeMm:.2,stroke:'#000000',fill:'none'},{id:'text-1',type:'text',xMm:8,yMm:6,fontFamily:'font-aaaaaaaa-0000-4000-8000-000000000001',fontSizePt:12,text:'TEST · Città',fill:'#000000'}]:[{id:'text-1',type:'text',xMm:5,yMm:5,fontFamily:'font-aaaaaaaa-0000-4000-8000-000000000001',fontSizePt:12,text:'TEST',fill:'#000000'}];
 if(blue)doc.inkColor='blue';
 await store.dispatch({tool:'saveRecord',expectedRevision:0,arguments:{kind:'template',title:'Template TEST',tags:[],clientRef:'',document:doc}});const id=(await store.read()).records[0]!.id;
 await store.dispatch({tool:'templateProducts',expectedRevision:1,arguments:{id,products:{profileKeys:products.map(profileKey),initialMount:'smallest-compatible',adaptation:'confirm-proportional'}}});
 await page.route('**/__editor-local/admin/**',async route=>{if(new URL(route.request().url()).pathname.endsWith('/font-coverage'))return route.fallback();try{const state=await store.read(),path=new URL(route.request().url()).pathname.replace('/__editor-local/admin/','');await route.fulfill({json:route.request().method()==='POST'?await store.dispatch(route.request().postDataJSON()):path.startsWith('record/')?state.records.find(r=>r.id===path.slice(7)):adminSnapshot(state)});}catch(cause){await route.fulfill({status:422,json:{error:cause instanceof Error?cause.message:String(cause)}});}});
 return{store,id,doc,products,cleanup:()=>rm(directory,{recursive:true,force:true})};
}
