async function previewInkStats(page:Page,png:Buffer){return page.evaluate(async base64=>{const image=new Image();image.src=`data:image/png;base64,${base64}`;await image.decode();const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;const context=canvas.getContext('2d')!;context.drawImage(image,0,0);const bytes=context.getImageData(0,0,image.width,image.height).data;let blue=0,white=0,transparent=0;for(let i=0;i<bytes.length;i+=4){if(bytes[i+3]!>240&&bytes[i]!<20&&bytes[i+1]!<20&&bytes[i+2]!>180)blue++;if(bytes[i+3]!>240&&bytes[i]!>250&&bytes[i+1]!>250&&bytes[i+2]!>250)white++;if(bytes[i+3]===0)transparent++;}return{blue,white,transparent};},png.toString('base64'));}
