async function bulkAdminArchive(page:Page){
 const {mkdtemp,rm}=await import('node:fs/promises'),{join}=await import('node:path'),{tmpdir}=await import('node:os'),{EditorAdminStore,adminSnapshot}=await import('../../scripts/editor-admin-store'),{prepareManualFont}=await import('../../scripts/editor-font-upload');const directory=await mkdtemp(join(tmpdir(),'bulk-admin-browser-')),details=[11,22].map(n=>({source:'test' as const,checkedAt:new Date().toISOString(),id:`gid://shopify/Product/${n}`,title:`Prodotto TEST ${n}`,status:'ACTIVE' as const,variants:[1,2].map(v=>({id:`gid://shopify/ProductVariant/${n}${v}`,title:`Variante ${v}`,sku:null,selectedOptions:[]}))})),store=new EditorAdminStore(directory,async id=>{const detail=details.find(detail=>detail.id===id);if(!detail)throw new Error('Prodotto TEST non trovato');return detail;}),catalog={schemaVersion:1,source:'test',shopDomain:'zqu2eg-72.myshopify.com',checkedAt:new Date().toISOString(),collections:[{id:'gid://shopify/Collection/1',title:'Targhe TEST',handle:'targhe'}],products:details.map(detail=>({id:detail.id,title:detail.title,handle:`test-${detail.id.split('/').at(-1)}`,status:'ACTIVE',tags:['targhe'],collectionIds:['gid://shopify/Collection/1'],onlineStoreUrl:null,image:null}))};const writes:string[]=[];
 await page.route('**/__editor-local/admin/**',async route=>{if(new URL(route.request().url()).pathname.endsWith('/font-coverage'))return route.fallback();try{const path=new URL(route.request().url()).pathname.replace('/__editor-local/admin/',''),request=route.request();if(path==='font-inspect'){const {dataBase64,...metadata}=prepareManualFont(request.postDataJSON());return route.fulfill({json:metadata});}if(path==='shop-catalog')return route.fulfill({json:{configured:true,catalog,lastError:null}});if(path==='shop-product')return route.fulfill({json:details.find(detail=>detail.id===new URL(request.url()).searchParams.get('id'))});if(request.method()==='POST'){writes.push(request.postDataJSON().tool);return route.fulfill({json:await store.dispatch(request.postDataJSON())});}const state=await store.read();if(path.startsWith('record/'))return route.fulfill({json:state.records.find(record=>record.id===path.slice(7))});if(path.startsWith('font/')){const font=state.fonts.find(font=>font.id===path.slice(5));return font?route.fulfill({body:Buffer.from(font.dataBase64,'base64'),contentType:`font/${font.format}`}):route.fulfill({status:404,json:{error:'Font assente'}});}return route.fulfill({json:adminSnapshot(state)});}catch(cause){return route.fulfill({status:422,json:{error:cause instanceof Error?cause.message:String(cause)}});}});
 return {store,writes,details,cleanup:()=>rm(directory,{recursive:true,force:true})};
}

