test('avvio template: il primo documento visibile è quello richiesto anche con caricamento ritardato',async({page})=>{
 const archive=await templateArchive(page);let release!:()=>void;const gate=new Promise<void>(resolve=>release=resolve);let requested=false;
 try{
  const state=await archive.store.read(),record=state.records[0]!,doc=structuredClone(record.document);
  doc.objects=[{id:'solo-template',type:'rect',xMm:5,yMm:5,widthMm:20,heightMm:10,stroke:'#000000',strokeMm:.2,fill:'none'}];
  await archive.store.dispatch({tool:'replaceRecord',expectedRevision:state.revision,arguments:{id:record.id,recordVersion:record.version,title:record.title,tags:record.tags,document:doc}});
  const updated=(await archive.store.read()).records[0]!,product=archive.products.find(item=>item.handle==='trodat-4915')!;
  await page.addInitScript(()=>{
   const seen:string[][]=[];(window as any).__openingDocuments=seen;
   new MutationObserver(()=>{const state=document.querySelector('[data-testid="graphic-state"]');if(state?.textContent){const doc=JSON.parse(state.textContent);seen.push(doc.objects.map((object:any)=>object.id));}}).observe(document,{childList:true,subtree:true,characterData:true});
  });
  await page.route(`**/__editor-local/admin/record/${archive.id}`,async route=>{requested=true;await gate;return route.fallback();});
  const query=new URLSearchParams({workspace:'1',mode:'customer',format:product.profileId??product.productId,template:archive.id,templateVersion:String(updated.version)});
  await page.goto(`/editor?${query}`);await expect.poll(()=>requested).toBe(true);
  await expect(page.locator('.canvas-container')).toHaveCount(0);await expect(page.getByTestId('graphic-state')).toHaveCount(0);release();
  await expect(page.getByTestId('editor-workspace')).toHaveAttribute('data-view-ready','true');
  await expect.poll(async()=>(await refinementState(page)).templateOrigin?.id).toBe(archive.id);
  const seen=await page.evaluate(()=>(window as any).__openingDocuments as string[][]);expect(seen.length).toBeGreaterThan(0);expect(seen.every(ids=>ids.length===1&&ids[0]==='solo-template')).toBe(true);
  expect((await archive.store.read()).records[0]).toEqual(updated);
 }finally{release?.();await archive.cleanup();}
});

