o(45.678912,8);expect(result.xMm).toBeCloseTo(2.3,8);expect(result.yMm).toBeCloseTo(3.4,8);expect(result.crop).toBe('3.125 2.625 3990.375 990.125');expect(result.same&&result.original&&result.documentUnchanged).toBe(true);
