  const prepared=await page.evaluate(async()=>{const h='/tests/helpers/browser-module.ts',{loadedEditorModule}=await import(h),{rasterCanvas}=await import(loadedEditorModule('/src/editor/raster-cache.ts')),doc=JSON.parse(document.querySelector('[data-testid="graphic-state"]')!.textContent!),canvases=doc.objects.map((o:any)=>rasterCanvas(o.source,o.raster));return{different:canvases[0]!==canvases[1],same:rasterCanvas(doc.objects[0].source,doc.objects[0].raster)===canvases[0],pixels:canvases.map((c:HTMLCanvasElement)=>Array.from(c.getContext('2d')!.getImageData(0,0,1,1).data))};});expect(prepared).toEqual({different:true,same:true,pixels:[[0,136,204,255],[204,85,0,255]]});
  await page.getByRole('button',{name:'Annulla',exact:true}).click();const undone=await refinementState(page);await page.getByRole('button',{name:'Esegui comando',exact:true}).click();await expect(page.getByRole('alert')).toContainText('obsoleta');expect(await refinementState(page)).toEqual(undone);await page.getByRole('button',{name:'Ripristina',exact:true}).click();const valid=await refinementState(page);expect(valid.objects[0].source).toEqual(before.objects[0].source);
  await input.fill(JSON.stringify({schemaVersion:1,tool:'updateObject',objectId:valid.objects[0].id,expectedRevision:valid.revision,arguments:{object:{...valid.objects[0],raster:{...valid.objects[0].raster,mode:'original'}}}}));await page.getByRole('button',{name:'Esegui comando',exact:true}).click();await expect(page.getByRole('alert')).toContainText('modalità originale');expect(await refinementState(page)).toEqual(valid);
