async function mediaHarness(page:Page){
 const {mkdtemp,rm}=await import('node:fs/promises'),{tmpdir}=await import('node:os'),{join}=await import('node:path'),{EditorMediaStore}=await import('../../scripts/editor-media-store'),directory=await mkdtemp(join(tmpdir(),'media-browser-TEST-')),store=new EditorMediaStore(directory),bytes=testPng(4,2,new Uint8Array([255,0,0,255,255,255,255,255,0,0,255,255,0,255,0,255,255,0,0,255,255,255,255,255,0,0,255,255,0,255,0,255]));
 let state=await store.dispatch({tool:'category',expectedRevision:0,arguments:{kind:'picture',title:'Simboli TEST'}});const category=state.categories[0]!.id;
 const upload=async(kind:'picture'|'background',title:string,usage='print',data=bytes)=>{state=await store.dispatch({tool:'upload',expectedRevision:state.revision,arguments:{kind,title,categories:kind==='picture'?[category]:[],usage,...(title.includes('SVG')?{defaultWidthMm:50}:{}),dataBase64:data.toString('base64'),thumbnailBase64:bytes.toString('base64'),width:kind==='picture'&&title.includes('SVG')?40:4,height:kind==='picture'&&title.includes('SVG')?20:2}});};
 await upload('picture','Foto TEST');await upload('picture','SVG TEST','print',Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="40" height="20"><rect x="0" y="0" width="40" height="20" fill="#cc2200"/></svg>'));await upload('background','Sfondo TEST');await upload('background','Materiale TEST','material');
 let uploads=0;await page.route('**/__editor-local/media/**',async route=>{const path=new URL(route.request().url()).pathname.split('/').filter(Boolean);try{if(route.request().method()==='POST'){uploads++;return route.fulfill({json:await store.dispatch(route.request().postDataJSON())});}if(path.length===2)return route.fulfill({json:await store.read()});const blob=await store.blob(path[3]!,path[2]==='thumbnail');return route.fulfill({body:blob.bytes,contentType:blob.mime});}catch(e){return route.fulfill({status:422,json:{error:e instanceof Error?e.message:String(e)}});}});
 const doc=createTestDocument();doc.fontAssets=[];doc.colorMode='color';doc.areaMm={width:100,height:80};doc.objects=[];await page.goto('/editor');await page.getByLabel('Riapri progetto JSON').setInputFiles({name:'media.TEST.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(doc))});return{store,bytes,category,uploads:()=>uploads,cleanup:()=>rm(directory,{recursive:true,force:true})};
}

