 const source=JSON.parse(await readFile('fixtures/illustrator/stroke-outlines.source.TEST.json','utf8'));await paperScene(page);const result=await page.evaluate(async source=>{const h='/tests/helpers/browser-module.ts',{loadedEditorModule}=await import(h),{importPitchPrint}=await import(loadedEditorModule('/src/editor/pitchprint-import.ts')),{FabricAdapter}=await import(loadedEditorModule('/src/editor/fabric-adapter.ts')),helper='/tests/helpers/pitchprint-page-reference.browser.ts',{pitchprintPageReferenceSvg}=await import(helper),converted=await importPitchPrint(source,{monochrome:false,excludeBackground:false,font:async()=>{throw Error('No font');},image:async()=>{throw Error('No image');}}),native=new FabricAdapter(document.createElement('canvas'),()=>0,()=>{});try{native.render(converted.document,[]);native.canvas.renderAll();const svg=await pitchprintPageReferenceSvg(source,[],{}),image=new Image();image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);await image.decode();const canvas=document.createElement('canvas');canvas.width=800;canvas.height=560;const c=canvas.getContext('2d')!;c.fillStyle='white';c.fillRect(0,0,800,560);c.drawImage(image,0,0,800,560);const a=c.getImageData(0,0,800,560).data,b=native.canvas.lowerCanvasEl.getContext('2d')!.getImageData(0,0,800,560).data;let interior=0,seams=0,maxDelta=0;const bad:any[]=[];for(let y=2;y<558;y++)for(let x=2;x<798;x++){const at=(y*800+x)*4;if(a[at]===255&&a[at+1]===255&&a[at+2]===255)continue;let solid=true;for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const i=((y+dy)*800+x+dx)*4;if(a[i]!==a[at]||a[i+1]!==a[at+1]||a[i+2]!==a[at+2])solid=false;}if(!solid)continue;interior++;const delta=Math.max(...[0,1,2].map(k=>Math.abs(a[at+k]!-b[at+k]!)));maxDelta=Math.max(maxDelta,delta);if(delta>2){seams++;if(bad.length<10)bad.push({x,y,delta,reference:Array.from(a.slice(at,at+4)),actual:Array.from(b.slice(at,at+4))});}}return{interior,seams,maxDelta,bad,commands:converted.document.objects.reduce((n:number,o:any)=>n+(o.commands?.length??0),0)};}finally{native.dispose();}},source);console.log('STROKE_CANVAS',JSON.stringify(result));expect(result.interior).toBeGreaterThan(20000);expect(result.seams).toBe(0);expect(result.maxDelta).toBeLessThanOrEqual(2);
