test('servizio contorni: il worker lascia reattivo il server e rifiuta elaborazioni simultanee',async({request})=>{
 test.setTimeout(45000);const url='http://127.0.0.1:5173/__editor-local/stroke-outlines',headers={'X-Editor-Local':'1',Origin:'http://127.0.0.1:5173'},r=200,k=r*.5522847498307936,commands=[['M',r,0],['C',r,k,k,r,0,r],['C',-k,r,-r,k,-r,0],['C',-r,-k,-k,-r,0,-r],['C',k,-r,r,-k,r,0],['Z']],body={schemaVersion:1,commands,matrix:[1.7,.2,.4,.8,400,300],strokeWidth:4,lineCap:'round',lineJoin:'round',miterLimit:4};let done=false;const work=request.post(url,{headers,data:body}).finally(()=>{done=true;});await new Promise(resolve=>setTimeout(resolve,30));const simultaneous=await request.post(url,{headers,data:body});expect(simultaneous.status()).toBe(429);const timings:number[]=[];for(let i=0;i<30&&!done;i++){const start=Date.now();expect((await request.get('http://127.0.0.1:5173/editor')).status()).toBe(200);timings.push(Date.now()-start);await new Promise(resolve=>setTimeout(resolve,50));}const result=await work;expect(result.status()).toBe(200);expect(timings.length).toBeGreaterThan(0);expect(Math.max(...timings)).toBeLessThan(1000);console.log('STROKE_SERVER_RESPONSIVE',JSON.stringify({polls:timings.length,maxMs:Math.max(...timings)}));
});
